steps.script:
$o=@{watchdogV15=$false;errors=@()}
try{$g=Get-Content 'C:\TTiTTulares\TT-LocalWatchdog.ps1' -Raw -ErrorAction Stop;$o.watchdogV15=$g.Contains('watchdog-v15-editorial-tab-cap-selfheal')}catch{}
foreach($n in @('ttittulares-mobile-trigger.log','ttendencias-mobile-trigger.log')){
 try{
  $a=@(Get-Content (Join-Path 'C:\TTiTTulares' $n) -Tail 120|Where-Object{$_ -like '*CHAT LAUNCH LOG ERROR*'})
  if($a.Count -eq 0){$o.errors+=@{file=$n;status='none'};continue}
  $s=[string]$a[-1];$s=$s -replace 'https?://\S+','[URL]' -replace '[a-zA-Z0-9+/]{40,}={0,2}','[DATA]'
  $o.errors+=@{file=$n;tail=$s.Substring([Math]::Max(0,$s.Length-160))}
 }catch{$o.errors+=@{file=$n;status='read_error'}}
}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress -Depth 4))
